  for(const p of ['strokeWeight','strokemiterLimit','strokeAlign','strokeCap','strokeJoin']){try{o[p]=node[p];}catch(e){}}
  try{ o.strokes = Array.isArray(node.strokes)? node.strokes.map(f=>({t:f.type})) : node.strokes; }catch(e){o.strokes='ERR';}
  if(node.children) o.children=node.children.map(deep);
  return o;
}
